import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DHmNT4rz.js";const p=JSON.parse('{"title":"Auth Patterns","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/auth.md","filePath":"develop/auth.md","lastUpdated":null}'),s={name:"develop/auth.md"};function d(i,e,c,l,u,n){return a(),o("div",null,[...e[0]||(e[0]=[r('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/auth.md" target="_blank" rel="noreferrer"><code>.agents/auth.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="auth-patterns" tabindex="-1">Auth Patterns <a class="header-anchor" href="#auth-patterns" aria-label="Permalink to &quot;Auth Patterns&quot;">​</a></h1><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><strong>Server</strong>: Better Auth handles <code>/auth/*</code> on the Hono server (<code>apps/server</code>)</li><li><strong>Client</strong>: <code>authClient</code> from <code>@saasweave/auth</code> (nanostore-based, client-side only)</li><li><strong>SSR</strong>: <code>$getUser</code> server function resolves session from request headers, forwards <code>Set-Cookie</code> for refresh</li><li><strong>Cookies</strong>: Prefer Better Auth defaults for reusable projects — <code>SameSite=Lax</code> supports OAuth and other redirect-based flows without custom per-project overrides</li></ul><h2 id="query-pattern" tabindex="-1">Query Pattern <a class="header-anchor" href="#query-pattern" aria-label="Permalink to &quot;Query Pattern&quot;">​</a></h2><p>Auth user query is defined in <code>@saasweave/auth</code>:</p><ul><li><code>getAuthUserQueryOptions()</code> — staleTime 5 min, gcTime 10 min, refetchOnWindowFocus &quot;always&quot;</li><li>Root route <code>beforeLoad</code> prefetches auth (non-blocking <code>prefetchQuery</code>)</li><li>Auth-guarded routes use blocking <code>ensureQueryData</code></li></ul><h2 id="route-guards" tabindex="-1">Route Guards <a class="header-anchor" href="#route-guards" aria-label="Permalink to &quot;Route Guards&quot;">​</a></h2><h3 id="protected-routes-auth-layout-group" tabindex="-1">Protected routes (<code>(auth)/</code> layout group) <a class="header-anchor" href="#protected-routes-auth-layout-group" aria-label="Permalink to &quot;Protected routes (`(auth)/` layout group)&quot;">​</a></h3><ul><li><code>beforeLoad</code> calls <code>ensureQueryData(getAuthUserQueryOptions())</code> with <code>revalidateIfStale: true</code></li><li>No user → redirects to <code>/sign-in?redirect=&lt;current-path&gt;</code></li><li>Client-side <code>useEffect</code> re-checks auth for session expiry</li></ul><h3 id="guest-only-routes-guest-layout-group" tabindex="-1">Guest-only routes (<code>(guest)/</code> layout group) <a class="header-anchor" href="#guest-only-routes-guest-layout-group" aria-label="Permalink to &quot;Guest-only routes (`(guest)/` layout group)&quot;">​</a></h3><ul><li>Authenticated users → redirected to stored redirect path</li><li><code>?redirect</code> param validated against route tree (sanitized)</li></ul><h2 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h2><p>Two auth middlewares exist for different sensitivity levels:</p><table tabindex="0"><thead><tr><th>Middleware</th><th>Behavior</th><th>Use case</th></tr></thead><tbody><tr><td><code>authMiddleware</code></td><td>Uses cached session (5-min cookie cache)</td><td>Normal protected pages</td></tr><tr><td><code>freshAuthMiddleware</code></td><td>Hits DB, bypasses cache</td><td>Sensitive operations (password change, etc.)</td></tr></tbody></table><p>Both set 401 status and throw on unauthorized.</p><h2 id="schema-extension" tabindex="-1">Schema Extension <a class="header-anchor" href="#schema-extension" aria-label="Permalink to &quot;Schema Extension&quot;">​</a></h2><p>When extending the Better Auth <code>user</code> or <code>session</code> schema, update all three layers together:</p><ul><li><strong>Server auth config</strong>: add the field under <code>additionalFields</code> in <code>packages/auth/src/index.ts</code></li><li><strong>Drizzle schema</strong>: add the matching column in <code>packages/db/src/schema/auth.schema.ts</code></li><li><strong>Client inference</strong>: keep <code>packages/auth/src/react/auth-client.ts</code> using <code>inferAdditionalFields&lt;typeof auth&gt;()</code> so custom fields stay typed on the client</li></ul><p>For DB-backed auth fields, also generate and apply a Drizzle migration after the schema change.</p><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><ul><li>Cross-domain auth setups still require deliberate cookie/domain/CORS configuration even with Better Auth defaults</li><li><code>SameSite=Strict</code> is usually too brittle for OAuth, email links, and other redirect-based auth flows</li><li>The auth query uses <code>refetchOnWindowFocus: &quot;always&quot;</code> for cross-tab session sync</li><li>Better Auth custom fields are not complete if you only add the DB column; the auth config and client inference must be updated too</li><li>In this repo, keep the main Drizzle relation graph in <code>packages/db/src/schema/relations.ts</code> with <code>defineRelations()</code>. Auth tables may add their own <code>defineRelationsPart()</code> in <code>packages/db/src/schema/auth.schema.ts</code>, and that part must be merged after the main relations in <code>packages/db/src/index.ts</code>.</li></ul>',22)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
